class SearchMatch:
    """Represents a single search match."""
    __slots__ = ['file_path', 'line_number', 'line_text', 'match_start', 'match_end']

    def __init__(self, file_path: str, line_number: int, line_text: str,
                 match_start: int, match_end: int):
        self.file_path = file_path
        self.line_number = line_number
        self.line_text = line_text
        self.match_start = match_start
        self.match_end = match_end

class SearchResults:
    """Holds all search results grouped by file."""
    def __init__(self):
        self.matches: List[SearchMatch] = []
        self.filtered_out: set = set()  # indices of filtered-out matches
        self.lock = threading.Lock()

    def add_match(self, match: SearchMatch):
        with self.lock:
            self.matches.append(match)

    def get_visible_matches(self) -> List[Tuple[int, SearchMatch]]:
        """Returns list of (original_index, match) for visible matches."""
        with self.lock:
            return [(i, m) for i, m in enumerate(self.matches) 
                    if i not in self.filtered_out]

    def filter_match(self, match_idx: int):
        """Filter out the match at given visible index."""
        with self.lock:
            visible = [(i, m) for i, m in enumerate(self.matches) 
                       if i not in self.filtered_out]
            if 0 <= match_idx < len(visible):
                orig_idx = visible[match_idx][0]
                self.filtered_out.add(orig_idx)

    def filter_file(self, match_idx: int):
        """Filter out all matches for the file at given visible index."""
        with self.lock:
            visible = [(i, m) for i, m in enumerate(self.matches) 
                       if i not in self.filtered_out]
            if 0 <= match_idx < len(visible):
                file_path = visible[match_idx][1].file_path
                for i, m in enumerate(self.matches):
                    if m.file_path == file_path:
                        self.filtered_out.add(i)

    @property
    def total_matches(self):
        with self.lock:
            return len(self.matches)

    @property
    def filtered_count(self):
        with self.lock:
            return len(self.filtered_out)

def search_file(filepath: str, pattern: re.Pattern) -> List[SearchMatch]:
    """Search a single file for pattern matches."""
    matches = []
    try:
        with open(filepath, 'r', errors='replace') as f:
            for line_num, line in enumerate(f, 1):
                line_text = line.rstrip('\n')
                for m in pattern.finditer(line_text):
                    matches.append(SearchMatch(
                        filepath, line_num, line_text,
                        m.start(), m.end()
                    ))
    except (IOError, OSError, UnicodeDecodeError):
        pass
    return matches

def build_regex(pattern: str, ignore_case: bool, smart_case: bool,
                word_regexp: bool, fixed_strings: bool, multiline: bool) -> Optional[re.Pattern]:
    """Build regex pattern from search options."""
    flags = 0
    if multiline:
        flags |= re.MULTILINE

    if ignore_case:
        flags |= re.IGNORECASE
    elif smart_case:
        if pattern == pattern.lower():
            flags |= re.IGNORECASE

    if fixed_strings:
        pattern = re.escape(pattern)

    if word_regexp:
        pattern = r'\b' + pattern + r'\b'

    try:
        return re.compile(pattern, flags)
    except re.error:
        return None

def run_search(files: List[str], pattern: re.Pattern, results: SearchResults,
               search_done_event: threading.Event, result_queue: queue.Queue,
               sort_by=None, sort_reverse=False):
    """Run search in background thread."""
    # Sort files if needed
    if sort_by == 'path':
        files = sorted(files, reverse=sort_reverse)
    elif sort_by == 'modified':
        files = sorted(files, key=lambda f: os.path.getmtime(f) if os.path.exists(f) else 0,
                       reverse=sort_reverse)
    elif sort_by == 'created':
        files = sorted(files, key=lambda f: os.path.getctime(f) if os.path.exists(f) else 0,
                       reverse=sort_reverse)
    elif sort_by == 'accessed':
        files = sorted(files, key=lambda f: os.path.getatime(f) if os.path.exists(f) else 0,
                       reverse=sort_reverse)

    for filepath in files:
        matches = search_file(filepath, pattern)
        for match in matches:
            results.add_match(match)
            result_queue.put(('new_match', None))

    search_done_event.set()
    result_queue.put(('search_done', None))

