def open_editor(file_path: str, line_number: int, editor: Optional[str],
                custom_command: str) -> Optional[str]:
    """Open file in editor. Returns error message or None on success."""
    cmd = None

    if custom_command:
        cmd = custom_command.replace('{file_name}', file_path).replace(
            '{line_number}', str(line_number))
    elif editor:
        template = EDITOR_COMMANDS.get(editor, '')
        if template:
            cmd = template.replace('{file_name}', file_path).replace(
                '{line_number}', str(line_number))
    else:
        # Try environment variables
        for env_var in ['IGREP_EDITOR', 'VISUAL', 'EDITOR']:
            val = os.environ.get(env_var, '')
            if val:
                # Check if it's a known editor name
                if val in EDITOR_COMMANDS:
                    template = EDITOR_COMMANDS[val]
                    cmd = template.replace('{file_name}', file_path).replace(
                        '{line_number}', str(line_number))
                else:
                    # Use it as a command directly
                    cmd = f'{val} {file_path}'
                break

    if not cmd:
        # Default: try vim
        cmd = f'vim +{line_number} {file_path}'
        editor_name = 'vim'
    else:
        # Extract editor name for error message
        editor_name = cmd.split()[0]

    # Check if editor exists
    editor_exec = cmd.split()[0]
    import shutil
    if not shutil.which(editor_exec):
        return f"Failed to open editor '{editor_exec}'. Is it installed?"

    try:
        subprocess.run(cmd, shell=True)
        return None
    except Exception as e:
        return str(e)

