class ColorManager:
    """Manages curses color pairs."""
    def __init__(self):
        self.pairs = {}
        self.next_pair = 1
        self.color_map = {}
        self.next_color = 16  # Start from 16 to avoid overwriting standard colors

    def init_colors(self, theme: dict):
        """Initialize all needed color pairs."""
        curses.start_color()
        curses.use_default_colors()

        if curses.can_change_color() and curses.COLORS >= 256:
            self._setup_rgb_colors(theme)
        else:
            self._setup_ansi_colors(theme)

    def _rgb_to_curses(self, r, g, b):
        """Convert RGB 0-255 to curses 0-1000."""
        return int(r * 1000 / 255), int(g * 1000 / 255), int(b * 1000 / 255)

    def _get_or_create_color(self, rgb_tuple):
        """Get or create a curses color index for RGB tuple."""
        if rgb_tuple is None:
            return -1
        if rgb_tuple in self.color_map:
            return self.color_map[rgb_tuple]

        if self.next_color < curses.COLORS:
            idx = self.next_color
            r, g, b = self._rgb_to_curses(*rgb_tuple)
            try:
                curses.init_color(idx, r, g, b)
                self.color_map[rgb_tuple] = idx
                self.next_color += 1
                return idx
            except:
                pass
        return -1

    def _setup_rgb_colors(self, theme: dict):
        """Setup colors with RGB support."""
        # Pre-define all needed colors
        pass

    def _setup_ansi_colors(self, theme: dict):
        """Setup colors using ANSI palette."""
        pass

    def get_pair(self, fg_rgb, bg_rgb) -> int:
        """Get a color pair number for fg/bg colors."""
        key = (fg_rgb, bg_rgb)
        if key in self.pairs:
            return self.pairs[key]

        fg_idx = self._get_or_create_color(fg_rgb)
        bg_idx = self._get_or_create_color(bg_rgb)

        pair_num = self.next_pair
        if pair_num < curses.COLOR_PAIRS:
            try:
                curses.init_pair(pair_num, fg_idx, bg_idx)
                self.pairs[key] = pair_num
                self.next_pair += 1
                return pair_num
            except:
                pass
        return 0

    def attr(self, fg_rgb, bg_rgb=None, bold=False) -> int:
        """Get curses attribute for fg/bg colors."""
        pair = self.get_pair(fg_rgb, bg_rgb)
        attr = curses.color_pair(pair)
        if bold:
            attr |= curses.A_BOLD
        return attr

