    def _get_context_lines(self, match: SearchMatch, max_lines: int = 20):
        """Get context lines around the match from the file."""
        lines = []
        try:
            with open(match.file_path, 'r', errors='replace') as f:
                all_lines = f.readlines()

            # Return all lines with the matched line highlighted
            for i, line in enumerate(all_lines):
                lines.append((i + 1, line.rstrip('\n'), i + 1 == match.line_number))
        except (IOError, OSError):
            pass
        return lines

    def _render_context_panel_vertical(self, win, panel_y, panel_x, panel_h, panel_w, visible):
        """Render vertical context panel (right side)."""
        if panel_w < 4:
            return

        theme = self.theme
        inner_h = panel_h - 2
        inner_w = panel_w - 2

        # Draw border
        try:
            win.addstr(panel_y, panel_x, '╭' + '─' * (panel_w - 2) + '╮')
            for i in range(1, panel_h - 1):
                win.addstr(panel_y + i, panel_x, '│')
                if panel_x + panel_w - 1 < win.getmaxyx()[1]:
                    win.addstr(panel_y + i, panel_x + panel_w - 1, '│')
            if panel_y + panel_h - 1 < win.getmaxyx()[0]:
                win.addstr(panel_y + panel_h - 1, panel_x, '╰' + '─' * (panel_w - 2) + '╯')
        except curses.error:
            pass

        if not visible or self.current_idx >= len(visible):
            return

        _, current_match = visible[self.current_idx]
        context_lines = self._get_context_lines(current_match)

        # Find where to start rendering - put matched line at top or context above
        sel_line_idx = None
        for i, (lnum, _, is_sel) in enumerate(context_lines):
            if is_sel:
                sel_line_idx = i
                break

        if sel_line_idx is None:
            return

        # Show context starting from beginning of file
        start = 0

        for row in range(inner_h):
            line_idx = start + row
            if line_idx >= len(context_lines):
                break

            lnum, text, is_sel = context_lines[line_idx]
            y = panel_y + 1 + row
            x_inner = panel_x + 1

            if is_sel:
                attr = self.cm.attr(theme['context_fg'], theme['selected_bg'])
                text_disp = text[:inner_w]
                self.safe_addstr(win, y, x_inner, text_disp, attr, inner_w)
                # Fill rest
                if len(text_disp) < inner_w:
                    fill_attr = self.cm.attr(None, theme['selected_bg'])
                    self.safe_addstr(win, y, x_inner + len(text_disp), 
                                    ' ' * (inner_w - len(text_disp)), fill_attr, inner_w)
            else:
                attr = self.cm.attr(theme['context_fg'], None)
                self.safe_addstr(win, y, x_inner, text[:inner_w], attr, inner_w)

