    def handle_key(self, key, visible) -> bool:
        """Handle a keypress. Returns True to continue, False to quit."""
        import curses

        # Keymap popup is open - any key closes it
        if self.show_keymap:
            self.show_keymap = False
            return True

        # Pattern input popup is open
        if self.show_pattern_input:
            return self._handle_pattern_input(key, visible)

        # Check for multi-char sequences
        now = time.time()

        # Handle 'g' + 'g' for goto first
        if key == ord('g'):
            if self.key_buffer == 'g' and (now - self.last_key_time) < 1.0:
                # gg - go to first match
                self.key_buffer = ''
                self.current_idx = 0
                self.scroll_offset = 0
                return True
            else:
                self.key_buffer = 'g'
                self.last_key_time = now
                return True

        # Handle 'd' sequences
        if key == ord('d'):
            if self.key_buffer == 'd' and (now - self.last_key_time) < 1.0:
                # dd - filter out current match
                self.key_buffer = ''
                if visible and self.current_idx < len(visible):
                    self.results.filter_match(self.current_idx)
                    visible_after = self.results.get_visible_matches()
                    if self.current_idx >= len(visible_after):
                        self.current_idx = max(0, len(visible_after) - 1)
                return True
            elif self.key_buffer == 'd' and (now - self.last_key_time) >= 1.0:
                # Timeout - reset buffer, start new 'd'
                self.key_buffer = 'd'
                self.last_key_time = now
                return True
            else:
                self.key_buffer = 'd'
                self.last_key_time = now
                return True

        # 'w' after 'd' = filter whole file
        if key == ord('w') and self.key_buffer == 'd' and (now - self.last_key_time) < 1.0:
            self.key_buffer = ''
            if visible and self.current_idx < len(visible):
                self.results.filter_file(self.current_idx)
                visible_after = self.results.get_visible_matches()
                if self.current_idx >= len(visible_after):
                    self.current_idx = max(0, len(visible_after) - 1)
            return True

        # Clear key buffer for other keys
        self.key_buffer = ''

        # Quit
        if key in (ord('q'), 27, 3):  # q, Esc, Ctrl+C
            return False

        # Help popup
        if key in (ord('?'), curses.KEY_F1):
            self.show_keymap = True
            return True

        # Navigation - Down / j
