            return True

        # Delete - filter out current match
        if key == curses.KEY_DC:
            if visible and self.current_idx < len(visible):
                self.results.filter_match(self.current_idx)
                visible_after = self.results.get_visible_matches()
                if self.current_idx >= len(visible_after):
                    self.current_idx = max(0, len(visible_after) - 1)
            return True

        # Toggle vertical context viewer
        if key == ord('v'):
            if self.context_viewer == 'vertical':
                self.context_viewer = 'none'
            else:
                self.context_viewer = 'vertical'
            return True

        # Toggle horizontal context viewer
        if key == ord('s'):
            if self.context_viewer == 'horizontal':
                self.context_viewer = 'none'
            else:
                self.context_viewer = 'horizontal'
            return True

        # Increase context viewer size
        if key == ord('+'):
            self.cv_size = min(self.cv_size + 1, 15)
            return True

        # Decrease context viewer size
        if key == ord('-'):
            self.cv_size = max(self.cv_size - 1, 2)
            return True

        # Open search pattern popup
        if key in (curses.KEY_F5, ord('/')):
            self.show_pattern_input = True
            self.pattern_input = self.pattern_str
            self.pattern_input_cursor = len(self.pattern_input)
            return True

        # Sorting
        if key == ord('n'):
            self.resort_results('path')
            return True
        if key == ord('m'):
            self.resort_results('modified')
            return True
        if key == ord('c'):
            self.resort_results('created')
            return True
        if key == ord('a'):
            self.resort_results('accessed')
            return True

        return True

    def _handle_pattern_input(self, key, visible) -> bool:
        """Handle key in pattern input mode."""
        if key in (curses.KEY_ENTER, 10, 13):
            # Submit new pattern
            self.show_pattern_input = False
            if self.pattern_input != self.pattern_str:
                self.pattern_str = self.pattern_input
                self.re_search_requested = True
            return True
        elif key == 27:  # Esc
            self.show_pattern_input = False
            return True
        elif key in (curses.KEY_BACKSPACE, 127, 8):
            if self.pattern_input_cursor > 0:
                self.pattern_input = (self.pattern_input[:self.pattern_input_cursor - 1] + 
                                     self.pattern_input[self.pattern_input_cursor:])
                self.pattern_input_cursor -= 1
        elif key == curses.KEY_LEFT:
            self.pattern_input_cursor = max(0, self.pattern_input_cursor - 1)
        elif key == curses.KEY_RIGHT:
            self.pattern_input_cursor = min(len(self.pattern_input), self.pattern_input_cursor + 1)
        elif key == curses.KEY_HOME:
            self.pattern_input_cursor = 0
        elif key == curses.KEY_END:
            self.pattern_input_cursor = len(self.pattern_input)
        elif 32 <= key < 127:
            ch = chr(key)
            self.pattern_input = (self.pattern_input[:self.pattern_input_cursor] + 
                                  ch + self.pattern_input[self.pattern_input_cursor:])
            self.pattern_input_cursor += 1

        return True

