def parse_args():
    parser = argparse.ArgumentParser(
        prog='ig',
        description='Interactive Grep',
        add_help=False,
    )

    parser.add_argument('pattern', metavar='PATTERN', nargs='?',
                        help='Regular expression used for searching')
    parser.add_argument('paths', metavar='PATHS', nargs='*',
                        help='Files or directories to search')

    parser.add_argument('--editor', dest='editor',
                        choices=EDITOR_CHOICES,
                        help='Text editor used to open selected match')
    parser.add_argument('--custom-command', dest='custom_command',
                        default=os.environ.get('IGREP_CUSTOM_EDITOR', ''),
                        help='Custom command used to open selected match')
    parser.add_argument('--theme', choices=['light', 'dark'], default='dark',
                        help='UI color theme')
    parser.add_argument('-i', '--ignore-case', action='store_true')
    parser.add_argument('-S', '--smart-case', action='store_true')
    parser.add_argument('-.', '--hidden', action='store_true')
    parser.add_argument('-L', '--follow', action='store_true')
    parser.add_argument('-w', '--word-regexp', action='store_true')
    parser.add_argument('-F', '--fixed-strings', action='store_true')
    parser.add_argument('-U', '--multiline', action='store_true')
    parser.add_argument('-g', '--glob', action='append', dest='globs', default=[])
    parser.add_argument('--type-list', action='store_true')
    parser.add_argument('-t', '--type', action='append', dest='type_matching', default=[])
    parser.add_argument('-T', '--type-not', action='append', dest='type_not', default=[])
    parser.add_argument('--context-viewer', choices=['none', 'vertical', 'horizontal'],
                        default='none')
    parser.add_argument('--sort', dest='sort_by',
                        choices=['path', 'modified', 'created', 'accessed'])
    parser.add_argument('--sortr', dest='sort_by_reverse',
                        choices=['path', 'modified', 'created', 'accessed'])
    parser.add_argument('-h', '--help', action='help')
    parser.add_argument('-V', '--version', action='version',
                        version=f'igrep {VERSION}')

    return parser.parse_args()


def fnmatch_extended(name: str, pattern: str) -> bool:
    """Match with bracket expressions in pattern."""
    return fnmatch.fnmatchcase(name, pattern) or fnmatch.fnmatch(name, pattern)


def matches_type(filename: str, type_names: List[str]) -> bool:
    basename = os.path.basename(filename)
    for type_name in type_names:
        patterns = FILE_TYPES.get(type_name, [])
        for pattern in patterns:
            if fnmatch_extended(basename, pattern):
                return True
    return False


def matches_glob(filepath: str, globs: List[str]) -> bool:
    basename = os.path.basename(filepath)
    for g in globs:
        if fnmatch.fnmatch(basename, g) or fnmatch.fnmatch(filepath, g):
            return True
    return False


def find_git_root(path: str) -> Optional[str]:
    """Find git root directory for the given path."""
    check = os.path.abspath(path)
    while True:
        if os.path.isdir(os.path.join(check, '.git')):
            return check
        parent = os.path.dirname(check)
        if parent == check:
            return None
        check = parent


class GitignoreRules:
    """Manages gitignore rules for a directory tree."""
    def __init__(self, git_root: str):
        self.git_root = git_root
        self.rules: Dict[str, List[str]] = {}

    def get_rules(self, directory: str) -> List[str]:
        if directory not in self.rules:
            patterns = []
            gitignore = os.path.join(directory, '.gitignore')
            if os.path.isfile(gitignore):
                try:
                    with open(gitignore, 'r', errors='replace') as f:
                        for line in f:
                            line = line.rstrip('\n')
                            if line and not line.startswith('#'):
                                patterns.append(line)
                except (IOError, OSError):
                    pass
            self.rules[directory] = patterns
        return self.rules[directory]

    def is_ignored(self, path: str, is_dir: bool = False) -> bool:
        """Check if path is ignored by gitignore rules."""
        # Collect all parent directories' rules
        abs_path = os.path.abspath(path)
        basename = os.path.basename(abs_path)

        # Walk from git root down to file's parent
        parent = os.path.dirname(abs_path)
        check_dirs = []
        cur = parent
        while cur.startswith(self.git_root):
            check_dirs.append(cur)
            if cur == self.git_root:
                break
            cur = os.path.dirname(cur)

        for check_dir in check_dirs:
            rules = self.get_rules(check_dir)
            for rule in rules:
                neg = rule.startswith('!')
                if neg:
                    rule = rule[1:]

                # Check if rule matches
                if self._pattern_matches(basename, abs_path, check_dir, rule, is_dir):
                    if neg:
                        return False
                    return True
        return False

    def _pattern_matches(self, basename: str, abs_path: str, base_dir: str,
                         pattern: str, is_dir: bool) -> bool:
        # Directory-only pattern
        if pattern.endswith('/'):
            if not is_dir:
                return False
            pattern = pattern.rstrip('/')

        # Anchored pattern (contains /)
        if '/' in pattern:
            rel = os.path.relpath(abs_path, self.git_root)
            return fnmatch.fnmatch(rel, pattern) or fnmatch.fnmatch(rel, pattern.lstrip('/'))

        # Simple pattern
        return fnmatch.fnmatch(basename, pattern)


def walk_files(paths: List[str], hidden: bool, follow_links: bool,
               type_matching: List[str], type_not: List[str], 
               globs: List[str]) -> List[str]:
    """Walk directories and return list of matching files."""
    results = []

    for input_path in paths:
        abs_path = os.path.abspath(input_path)

        if os.path.isfile(abs_path):
            results.append(abs_path)
            continue

        if not os.path.isdir(abs_path):
            continue

        # Find git root for this directory
        git_root = find_git_root(abs_path)
        gi_rules = GitignoreRules(git_root) if git_root else None

        for root, dirs, files in os.walk(abs_path, followlinks=follow_links):
            # Filter hidden dirs (always skip .git)
            if not hidden:
                dirs[:] = [d for d in dirs 
                           if not d.startswith('.')]
            else:
                dirs[:] = [d for d in dirs if d != '.git']

            dirs.sort()

            # Filter dirs by gitignore
            if gi_rules:
                new_dirs = []
                for d in dirs:
                    d_path = os.path.join(root, d)
                    if not gi_rules.is_ignored(d_path, is_dir=True):
                        new_dirs.append(d)
                dirs[:] = new_dirs

            for fname in sorted(files):
                fpath = os.path.join(root, fname)

                # Skip hidden
                if not hidden and fname.startswith('.'):
                    continue

                # Check gitignore
                if gi_rules and gi_rules.is_ignored(fpath, is_dir=False):
                    continue

                # Type filtering
                if type_matching and not matches_type(fname, type_matching):
                    continue
                if type_not and matches_type(fname, type_not):
                    continue

                # Glob filtering
                if globs and not matches_glob(fpath, globs):
                    continue

                results.append(fpath)

    return results

