class SearchMatch:
    __slots__ = ['file_path', 'line_number', 'line_text', 'match_start', 'match_end']

    def __init__(self, file_path: str, line_number: int, line_text: str,
                 match_start: int, match_end: int):
        self.file_path = file_path
        self.line_number = line_number
        self.line_text = line_text
        self.match_start = match_start
        self.match_end = match_end


class SearchResults:
    def __init__(self):
        self._matches: List[SearchMatch] = []
        self._filtered: Set[int] = set()
        self._lock = threading.Lock()

    def add(self, match: SearchMatch):
        with self._lock:
            self._matches.append(match)

    def get_visible(self) -> List[Tuple[int, SearchMatch]]:
        with self._lock:
            return [(i, m) for i, m in enumerate(self._matches)
                    if i not in self._filtered]

    def filter_match(self, visible_idx: int):
        with self._lock:
            visible = [i for i in range(len(self._matches)) if i not in self._filtered]
            if 0 <= visible_idx < len(visible):
                self._filtered.add(visible[visible_idx])

    def filter_file(self, visible_idx: int):
        with self._lock:
            visible = [i for i in range(len(self._matches)) if i not in self._filtered]
            if 0 <= visible_idx < len(visible):
                fp = self._matches[visible[visible_idx]].file_path
                for i, m in enumerate(self._matches):
                    if m.file_path == fp:
                        self._filtered.add(i)

    def resort(self, key_fn):
        with self._lock:
            self._matches.sort(key=key_fn)
            self._filtered = set()

    @property
    def total(self):
        with self._lock:
            return len(self._matches)

    @property
    def filtered_count(self):
        with self._lock:
            return len(self._filtered)


def build_regex(pattern: str, ignore_case: bool, smart_case: bool,
                word_regexp: bool, fixed_strings: bool, multiline: bool) -> Optional[re.Pattern]:
    flags = re.MULTILINE if multiline else 0

    if ignore_case:
        flags |= re.IGNORECASE
    elif smart_case and pattern == pattern.lower():
        flags |= re.IGNORECASE

    if fixed_strings:
        pattern = re.escape(pattern)

    if word_regexp:
        pattern = r'\b(?:' + pattern + r')\b'

    try:
        return re.compile(pattern, flags)
    except re.error:
        return None


def open_editor(file_path: str, line_number: int, 
                editor: Optional[str], custom_command: str) -> Optional[str]:
    """Open file in editor. Returns error message or None."""

    def subst(s):
        return s.replace('{file_name}', file_path).replace('{line_number}', str(line_number))

    if custom_command:
        cmd_parts = custom_command.split()
        cmd_parts = [subst(p) for p in cmd_parts]
        exec_name = cmd_parts[0]
    elif editor:
        template = EDITOR_COMMANDS.get(editor, [])
        if template:
            cmd_parts = [subst(p) for p in template]
            exec_name = cmd_parts[0]
        else:
            return f"Unknown editor: {editor}"
    else:
        # Try env vars
        exec_name = None
        for env_var in ['IGREP_EDITOR', 'VISUAL', 'EDITOR']:
            val = os.environ.get(env_var, '').strip()
            if val:
                if val in EDITOR_COMMANDS:
                    template = EDITOR_COMMANDS[val]
                    cmd_parts = [subst(p) for p in template]
                    exec_name = cmd_parts[0]
                else:
                    # Treat as executable name
                    cmd_parts = [val, file_path]
                    exec_name = val
                break

        if not exec_name:
            # Default vim
            cmd_parts = ['vim', f'+{line_number}', file_path]
            exec_name = 'vim'

    # Check if executable exists
    if not shutil.which(exec_name):
        return f"Failed to open editor '{exec_name}'. Is it installed?"

    try:
        subprocess.run(cmd_parts)
        return None
    except Exception as e:
        return str(e)


def search_worker(files: List[str], pattern: re.Pattern,
                  results: SearchResults, done_event: threading.Event,
                  notify_queue: queue.Queue):
    """Background search worker."""
    for fpath in files:
        try:
            with open(fpath, 'r', errors='replace') as f:
                for lnum, line in enumerate(f, 1):
                    text = line.rstrip('\n')
                    for m in pattern.finditer(text):
                        results.add(SearchMatch(fpath, lnum, text, m.start(), m.end()))
                        notify_queue.put(True)
        except (IOError, OSError):
            pass

    done_event.set()
    notify_queue.put(None)  # sentinel

